# ACI REST API — Create Tenant, VRF, Bridge Domain, EPG, Contract
# Create Tenant
POST https://apic-ip/api/mo/uni.json
{
  "fvTenant": {
    "attributes": {"name": "TENANT-PROD"},
    "children": [{
      "fvCtx": {"attributes": {"name": "VRF-PROD", "enforceCap": "enforced"}}
    }]
  }
}

# Create EPGs and Contract
POST https://apic-ip/api/mo/uni/tn-TENANT-PROD.json
{
  "fvTenant": {
    "children": [
      {"fvAp": {
        "attributes": {"name": "APP-PROD"},
        "children": [
          {"fvAEPg": {"attributes": {"name": "WEB", "prio": "level3"},
            "children": [{"fvRsBd": {"attributes": {"tnFvBDName": "BD-WEB"}}}]}},
          {"fvAEPg": {"attributes": {"name": "APP", "prio": "level3"},
            "children": [{"fvRsBd": {"attributes": {"tnFvBDName": "BD-APP"}}}]}}
        ]}
      },
      {"vzBrCP": {
        "attributes": {"name": "WEB-TO-APP", "scope": "context"},
        "children": [{
          "vzSubj": {
            "attributes": {"name": "HTTPS-TO-APP"},
            "children": [{
              "vzRsSubjGraphAtt": {},
              "vzRsSubjFiltAtt": [{"attributes": {"tnVzFilterName": "tcp-8080"}}]
            }]
          }
        }]
      }}
    ]
  }
}

# NSX — Create Logical Switch
POST https://nsx-mgr/api/v1/logical-switches
{
  "display_name": "LS-WEB-TIER",
  "transport_zone_id": "tz-uuid",
  "replication_mode": "MTEP",
  "admin_state": "UP"
}

# NSX — Distributed Firewall Rule
PUT https://nsx-mgr/api/v1/firewall/sections
{
  "display_name": "WEB-TO-APP",
  "rules": [{
    "display_name": "Allow HTTPS to App Tier",
    "source_groups": ["/infra/domains/default/groups/WEB-VM-GROUP"],
    "destination_groups": ["/infra/domains/default/groups/APP-VM-GROUP"],
    "services": ["/infra/services/HTTPS"],
    "action": "ALLOW",
    "logged": true
  }]
}
